static unsigned checks;
static unsigned idx;
static void number(unsigned n) {
    if(n>=10)number(n/10);
    putchar('0'+n%10);
}
static int fail(const char *s) {
    puts("FAIL"); puts(s); number(idx); putchar('\n');
    puts("Press a key"); getchar(); return 1;
}
static int eq(const Wide *a,const Wide *b) {
    return a->lo==b->lo && a->hi==b->hi;
}
#define CHECK(c,s) do { ++checks; if(!(c))return fail(s); } while(0)
#define BIN(fn,field) do { \
    a=t->a; b=t->b; fn(&out,&a,&b); CHECK(eq(&out,&t->field),#fn " separate"); \
    a=t->a; b=t->b; fn(&a,&a,&b); CHECK(eq(&a,&t->field),#fn " alias a"); \
    a=t->a; b=t->b; fn(&b,&a,&b); CHECK(eq(&b,&t->field),#fn " alias b"); \
} while(0)
#define UN(fn,field) do { \
    a=t->a; fn(&out,&a); CHECK(eq(&out,&t->field),#fn " separate"); \
    a=t->a; fn(&a,&a); CHECK(eq(&a,&t->field),#fn " alias"); \
} while(0)
#define SHIFT(fn,field) do { \
    a=t->a; fn(&out,&a,t->shift); CHECK(eq(&out,&t->field),#fn " separate"); \
    a=t->a; fn(&a,&a,t->shift); CHECK(eq(&a,&t->field),#fn " alias"); \
} while(0)
int main(void) {
    Wide a,b,out;
    const struct Test *t;
    puts("TINY 10C WIDE ABI TEST");
    for(idx=0;idx<sizeof(cases)/sizeof(cases[0]);++idx) {
        t=&cases[idx];
        BIN(wa,add); BIN(ws,sub); BIN(wm,mul);
        if(t->b.lo || t->b.hi){BIN(tiny_wdiv,div); BIN(tiny_wrounddiv,round);}
        UN(wneg,neg); UN(wmag,mag); SHIFT(wl,left); SHIFT(wr,right);
        a=t->a; b=t->b;
        CHECK(wc(&a,&b)==t->ucmp,"wc"); CHECK(wcs(&a,&b)==t->scmp,"wcs");
        CHECK(wz(&a)==t->zero,"wz"); CHECK(wn(&a)==t->negative,"wn");
        CHECK(topbit(&a)==t->top,"topbit"); CHECK(wbit(&a,t->shift)==(unsigned)t->bit,"wbit");
        winc(&a); CHECK(eq(&a,&t->inc),"winc");
    }
    puts("PASS"); number(checks); puts(" checks"); puts("Press a key"); getchar();
    return 0;
}
